<?php
require __DIR__.'/app/bootstrap.php';
$userId=require_auth();$pdo=db();$service=new VacationPhotoService($pdo,__DIR__);$error=null;$success=flash('success');$generated=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        $action=(string)($_POST['action']??'');
        if($action==='consent'){$service->setConsent($userId,!empty($_POST['ai_photo_consent']));flash('success',!empty($_POST['ai_photo_consent'])?'AI vacation-photo consent is on. You choose the photos and destinations every time.':'AI vacation-photo consent is off. Existing generated images remain in your private gallery.');redirect('vacation-yourself.php');}
        if($action==='add_reference'){$service->addReference($userId,$_FILES['reference_photo']??[],(string)($_POST['label']??''));flash('success','Reference photo added.');redirect('vacation-yourself.php');}
        if($action==='remove_reference'){$service->removeReference($userId,(int)($_POST['reference_id']??0));flash('success','Reference photo removed.');redirect('vacation-yourself.php');}
        if($action==='generate'){$generated=$service->generate($userId,$_POST);$success='Your imaginary vacation evidence has arrived.';}
    }catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'Vacation Brain could not create that image. '.($e->getMessage()!==''?$e->getMessage():'Please try again.');}
}
$preference=$service->preference($userId);$references=$service->referenceCandidates($userId);$history=$service->history($userId,36);$openai=(new AiProviderService($pdo))->get('openai',false);$providerReady=$openai&&!empty($openai['enabled'])&&!empty($openai['has_key']);
$title='Vacation Yourself';require __DIR__.'/partials/header.php';
?>
